using L_INT = std::numeric_limits<int>;
using L_DBL = std::numeric_limits<double>;

// Compile-Time Information Retrieval
constexpr int char_bits = std::numeric_limits<char>::digits;

// Polymorphic access via type T
constexpr double min_d = L_DBL::min();
constexpr double max_d = L_DBL::max();

// Implementation detail: trait specification
static_assert(L_INT::is_specialized);
static_assert(L_DBL::is_iec559);

// Usage in constexpr context
template <typename T>
constexpr bool is_signed() {
    return std::numeric_limits<T>::is_signed;
}

static_assert(is_signed<long>());
static_assert(!is_signed<size_t>());
